 static int Main(string[] args){var log=new StringBuilder();IntPtr radio=IntPtr.Zero,radioFind=IntPtr.Zero,find=IntPtr.Zero;try{if(args.Length!=2||args[0]!="--enable-hfp"||String.IsNullOrWhiteSpace(args[1]))throw new ArgumentException("Explicit device name and --enable-hfp required");if(PhoneCallManager.IsCallActive||PhoneCallManager.IsCallIncoming)throw new Exception("Active/incoming call; no configuration changed");var rs=new RadioSearch{Size=(uint)Marshal.SizeOf(typeof(RadioSearch))};radioFind=BluetoothFindFirstRadio(ref rs,out radio);if(radioFind==IntPtr.Zero)throw new Exception("Bluetooth radio unavailable");IntPtr second;if(BluetoothFindNextRadio(radioFind,out second)){CloseHandle(second);throw new Exception("Multiple Bluetooth radios; target must be explicit");}var search=new Search{Size=(uint)Marshal.SizeOf(typeof(Search)),Authenticated=true,Remembered=true,Connected=true,Radio=radio};var device=new Device{Size=(uint)Marshal.SizeOf(typeof(Device))};find=BluetoothFindFirstDevice(ref search,ref device);if(find==IntPtr.Zero)throw new Exception("No authenticated Classic device");var selected=new Device();int matches=0;do{if(device.Name==args[1]&&device.Authenticated){selected=device;matches++;}device.Size=(uint)Marshal.SizeOf(typeof(Device));}while(BluetoothFindNextDevice(find,ref device));if(matches!=1)throw new Exception("Expected exactly one matching authenticated phone");Guid hfp=new Guid("0000111f-0000-1000-8000-00805f9b34fb");uint count=64;var enabled=new Guid[64];uint hr=BluetoothEnumerateInstalledServices(radio,ref selected,ref count,enabled);log.AppendLine("ServicesBefore="+count+";Result="+hr);if(hr!=0)throw new Exception("Could not read services");for(int i=0;i<count;i++)if(enabled[i]==hfp){log.AppendLine("HFP=AlreadyEnabled;NoChange");return 0;}hr=BluetoothSetServiceState(radio,ref selected,ref hfp,1);log.AppendLine("EnableHfpResult="+hr+";Hex="+hr.ToString("X8"));if(hr!=0)return 1;count=64;hr=BluetoothEnumerateInstalledServices(radio,ref selected,ref count,enabled);bool present=false;if(hr==0)for(int i=0;i<count;i++)if(enabled[i]==hfp)present=true;log.AppendLine("ServicesAfter="+count+";HfpEnabled="+present);return present?0:2;}catch(Exception ex){log.AppendLine("Error="+ex.HResult.ToString("X8")+";"+ex.Message);return 1;}finally{if(find!=IntPtr.Zero)BluetoothFindDeviceClose(find);if(radioFind!=IntPtr.Zero)BluetoothFindRadioClose(radioFind);if(radio!=IntPtr.Zero)CloseHandle(radio);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"enable-iphone-hfp.local.txt"),log.ToString());}}
